import { Component, input } from '@angular/core';
import { StatusSummary } from './summary-panel';
import { FigurePipe } from '../../core/figure';

// The sheet's counters, always on top: how many people it has (retired included), how many
// claims are in each status, and its due-total and overdue-total, each the figure it repeats;
// and the signed-in user's own due-total and overdue-total, when a person on the sheet is theirs,
// and their crew total, when that person leads a crew; and how many claims in review are assigned
// to them.
@Component({
  selector: 'app-header-counters',
  imports: [FigurePipe],
  template: `
    <header aria-label="Sheet counters" data-testid="header">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() }}</dd>
        @for (s of statuses(); track s.status) {
          <dt>{{ s.status }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd>
        }
        <dt>Due</dt>
        <dd data-testid="header-due-total">{{ dueTotal() | figure }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() | figure }}</dd>
        <dt>My due</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() | figure }}</dd>
        <dt>My overdue</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() | figure }}</dd>
        <dt>My crews' due</dt>
        <dd data-testid="my-crew-due-total">{{ myCrewDueTotal() | figure }}</dd>
        <dt>My reviews</dt>
        <dd data-testid="my-reviews-count">{{ myReviewsCount() }}</dd>
      </dl>
    </header>
  `,
})
export class HeaderCounters {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
  /** The signed-in user's own due-total and overdue-total: blank when no person on the sheet has
   *  their name or alias. */
  readonly myDueTotal = input.required<string>();
  readonly myOverdueTotal = input.required<string>();
  /** The due-totals of the crews the signed-in user's person leads, added up: blank when they lead
   *  none. */
  readonly myCrewDueTotal = input.required<string>();
  /** How many claims in review on the sheet are assigned to the signed-in user. */
  readonly myReviewsCount = input.required<number>();
}
const NO_LEAVE: Leave = { holds: [], retiredFrom: null };

// The people on the sheet, in the order they were added, and the form that adds a person or,
// once a person's editor is opened, edits them. Each person's row lists their claims and what
// they have claimed and are due at their grade's rate; the sheet's totals add everyone's up.
// Retired people are left out of the list unless "show retired" is on; their claims still count.
// A person's holds take none of their claims out of any total: a held person only gets no cut of
// the pools, their share spread over the others. From the day the sheet's today
// reaches a person's retirement day, none of their open claims a statement did not bind counts either.
// A person may name other people on the sheet as their patrons; their backing is the settled
// figures of their patrons' settled claims dated within the 90 days up to the sheet's today, each
// patron's weighted by their share (100.00 split equally in the order they were named).
// The signed-in user may watch a person: they are told when a claim of theirs is settled.
@Component({
  selector: 'app-people-list',
  imports: [ReactiveFormsModule, PersonClaims, RateForm, PeriodForm, QuickAddBar, PasteClaimsBox, ImportPeopleBox, SummaryPanel, ClassicSummaryPanel, HeaderCounters, StewardDashboard, PoolList, CrewList, PersonPlans, PlanGenerateBox, TreeSearchBox, SheetCompareBox, FigurePipe],
  template: `
    <app-header-counters [peopleCount]="people().length" [statuses]="statusSummary()"
      [dueTotal]="dueTotal()" [overdueTotal]="overdueTotal()"
      [myDueTotal]="myDueTotal()" [myOverdueTotal]="myOverdueTotal()" [myCrewDueTotal]="myCrewDueTotal()"
      [myReviewsCount]="myReviewsCount()" />
    <app-steward-dashboard [steward]="myRole() === 'steward'" [statuses]="statusSummary()"
      [overdueCount]="overdueCount()" />
    <app-rate-form [rates]="rates()" (saved)="rateSaved($event)" (imported)="ratesImported()" />
    <app-period-form [periods]="periods()" [dueTotals]="periodDueTotals()" (saved)="periodSaved($event)"
      (removed)="periodRemoved($event)" />
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form data-testid="person-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="person-form-name">Name</label>
        <input id="person-form-name" data-testid="person-form-name" formControlName="name" />
        <label for="person-form-grade">Grade</label>
        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
